// Package web embeds the built Svelte frontend (frontend/, built with bun
// into web/dist) into the binary so the deployed app serves its UI with no
// filesystem access and no CDN at runtime.
package web

import (
	"embed"
	"io/fs"
)

// Dist is the production Svelte build (index.html + assets/). It is
// generated by `bun run build` in frontend/; a .gitkeep keeps the directory
// present so `go build` also works on a fresh checkout before the frontend
// has been built (the server then serves a "UI not built" placeholder).
//
//go:embed dist
var Dist embed.FS

// Sub returns the dist subtree as an fs.FS for http.FileServerFS.
func Sub() fs.FS {
	sub, err := fs.Sub(Dist, "dist")
	if err != nil {
		return Dist
	}
	return sub
}
